<?php if (($page ?? '') === 'login' || ($page ?? '') === 'register'): ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/style.css"></head><body class="auth-page"><main class="auth-card"><div class="brand"><span class="brand-mark">N</span><strong><?= e(APP_NAME) ?></strong></div><p class="eyebrow">PERSONAL FILE SPACE</p><h1><?= $page === 'login' ? 'Welcome back.' : 'Create your vault.' ?></h1><?php if ($flash): ?><div class="notice <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><?php if ($page === 'login'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="login"><label>Email<input type="email" name="email" required autofocus></label><label>Password<input type="password" name="password" required></label><button class="button primary wide">Sign in</button></form><p class="muted">New here? <a href="?page=register">Create an account</a></p><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="register"><label>Full name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password<input type="password" name="password" minlength="8" required></label><button class="button primary wide">Create account</button></form><p class="muted">Already registered? <a href="?page=login">Sign in</a></p><?php endif; ?></main></body></html><?php exit; endif; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e(APP_NAME) ?></title><link rel="stylesheet" href="assets/style.css"></head><body><aside class="sidebar"><div class="brand"><span class="brand-mark">N</span><strong><?= e(APP_NAME) ?></strong></div><nav><a class="<?= $view === 'all' ? 'active' : '' ?>" href="index.php"><span>⌂</span> My files</a><a class="<?= $view === 'recent' ? 'active' : '' ?>" href="?view=recent"><span>◷</span> Recent</a><a class="<?= $view === 'starred' ? 'active' : '' ?>" href="?view=starred"><span>☆</span> Starred</a><a class="<?= $view === 'trash' ? 'active' : '' ?>" href="?view=trash"><span>⌫</span> Trash</a></nav><div class="storage-box"><span>STORAGE USED</span><strong><?= e(format_bytes((int)$stats['used_bytes'])) ?> <small>/ 5 GB</small></strong><div class="progress"><i style="width:<?= min(100, ((int)$stats['used_bytes'] / 5368709120) * 100) ?>%"></i></div><small><?= e((int)$stats['item_count']) ?> files stored</small></div><div class="sidebar-user"><div class="avatar"><?= e(strtoupper(substr($current['name'], 0, 1))) ?></div><div><strong><?= e($current['name']) ?></strong><small><?= e($current['email']) ?></small></div><a href="?page=logout">↗</a></div></aside><main class="content"><header class="topbar"><div><p class="eyebrow">YOUR WORKSPACE</p><h1><?= $view === 'trash' ? 'Trash' : ($view === 'starred' ? 'Starred items' : ($view === 'recent' ? 'Recent activity' : 'My files')) ?></h1></div><form class="search" method="get"><input type="hidden" name="view" value="<?= e($view) ?>"><input name="q" value="<?= e($search) ?>" placeholder="Search your files"><button>⌕</button></form></header><?php if ($flash): ?><div class="notice <?= e($flash['type']) ?>"><?= e($flash['message']) ?></div><?php endif; ?><section class="actions"><form method="post" enctype="multipart/form-data" class="upload-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="upload"><input type="hidden" name="parent_id" value="<?= $folderId ?>"><label class="button primary">＋ Upload file<input type="file" name="file" onchange="this.form.submit()" hidden></label></form><button class="button" onclick="document.getElementById('folder-dialog').showModal()">＋ New folder</button></section><div class="file-grid"><?php foreach ($items as $item): ?><article class="file-card"><div class="file-icon <?= $item['item_type'] === 'folder' ? 'folder' : 'file' ?>"><?= $item['item_type'] === 'folder' ? '▰' : '▤' ?></div><div class="file-meta"><strong title="<?= e($item['name']) ?>"><?= e($item['name']) ?></strong><small><?= $item['item_type'] === 'folder' ? 'Folder' : e(format_bytes((int)$item['size_bytes'])) ?></small></div><div class="card-actions"><?php if ($view === 'trash'): ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="restore"><input type="hidden" name="item_id" value="<?= $item['id'] ?>"><button title="Restore">↶</button></form><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="toggle_star"><input type="hidden" name="item_id" value="<?= $item['id'] ?>"><button title="Star" class="<?= $item['is_starred'] ? 'starred' : '' ?>">★</button></form><?php if ($item['item_type'] === 'file'): ?><a href="?page=download&id=<?= $item['id'] ?>" title="Download">↓</a><?php else: ?><a href="?folder=<?= $item['id'] ?>" title="Open">→</a><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="trash"><input type="hidden" name="item_id" value="<?= $item['id'] ?>"><button title="Move to trash">⋯</button></form><?php endif; ?></div></article><?php endforeach; ?><?php if (!$items): ?><div class="empty"><div class="empty-icon">✦</div><h2>This space is ready for something great.</h2><p>Upload a file or create a folder to get started.</p></div><?php endif; ?></div></main><dialog id="folder-dialog"><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="create_folder"><input type="hidden" name="parent_id" value="<?= $folderId ?>"><h2>New folder</h2><label>Folder name<input name="name" required autofocus></label><div class="dialog-actions"><button type="button" class="button" onclick="this.closest('dialog').close()">Cancel</button><button class="button primary">Create folder</button></div></form></dialog><script src="assets/app.js"></script></body></html>
